package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeNumber(BigDecimal)
 */
public class TokenBuffer_writeNumber_TriageGen2Test {

    private ObjectCodec codec;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        codec = new ObjectMapper();
        tokenBuffer = new TokenBuffer(codec);
    }

    @Test
    public void testWriteNumber_WithNull() throws IOException {
        // Test branch: if (dec == null) -> writeNull()
        tokenBuffer.writeNumber((BigDecimal) null);

        // Verify behavior by serializing to a generator and checking output
        // Since writeNull() is called, the first token should be VALUE_NULL
        JsonGenerator gen = codec.getFactory().createGenerator(new java.io.StringWriter());
        tokenBuffer.serialize(gen);
        gen.flush();

        // We use a new parser to verify the content written to the buffer
        ObjectMapper mapper = new ObjectMapper();
        String json = gen.toString();
        assertEquals("null", json);
    }

    @Test
    public void testWriteNumber_WithValidBigDecimal() throws IOException {
        // Test branch: else { ; }
        BigDecimal value = new BigDecimal("123.456");
        tokenBuffer.writeNumber(value);

        // Verify the number was recorded correctly
        JsonGenerator gen = codec.getFactory().createGenerator(new java.io.StringWriter());
        tokenBuffer.serialize(gen);
        gen.flush();

        String json = gen.toString();
        assertEquals("123.456", json);
    }

    @Test
    public void testWriteNumber_WithZero() throws IOException {
        BigDecimal value = BigDecimal.ZERO;
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = codec.getFactory().createGenerator(new java.io.StringWriter());
        tokenBuffer.serialize(gen);
        gen.flush();

        assertEquals("0", gen.toString());
    }

    @Test
    public void testWriteNumber_WithLargeBigDecimal() throws IOException {
        BigDecimal value = new BigDecimal("12345678901234567890.1234567890");
        tokenBuffer.writeNumber(value);

        JsonGenerator gen = codec.getFactory().createGenerator(new java.io.StringWriter());
        tokenBuffer.serialize(gen);
        gen.flush();

        assertEquals("12345678901234567890.1234567890", gen.toString());
    }
}
